-- The castaway island (the user's wish, after Cast Away): a sand beach all round, widest in the south, a grassy
-- inland, a rocky peak in the north-west and a palm islet off the south-east. Grass tops are at y=0; sand lies a hand
-- lower (SAND_DROP), under and around the grass, so the two never draw the same surface. The renderer paints ground
-- and rock by the Surface attribute; the body treats sand as ground and rock as mesa.
local SAND_DROP = 0.1
local SAND_COLOR = Color3.fromRGB(232, 214, 166)
local GRASS_COLOR = Color3.fromRGB(108, 178, 72) -- a natural grass green, not upstream's mint
local ROCK_TERRAIN_COLOR = Color3.fromRGB(128, 124, 118)
local groundParts = {}
for n, r in ipairs(ISLAND.sand) do
    table.insert(groundParts, { name = "Beach_" .. n, size = {r[3], GROUND_HEIGHT, r[4]}, pos = {r[1], GROUND_Y, r[2]}, sand = true })
end
for n, r in ipairs(ISLAND.grass) do
    table.insert(groundParts, { name = "Ground_" .. n, size = {r[3], GROUND_HEIGHT, r[4]}, pos = {r[1], GROUND_Y, r[2]} })
end

for _, g in ipairs(groundParts) do
    local part = findWorkspaceChild(g.name) or Instance.new("Part")
    part.Name = g.name
    part.Size = Vector3.new(g.size[1], g.size[2], g.size[3])
    part.Position = Vector3.new(g.pos[1], GROUND_Y - (g.sand and SAND_DROP or 0), g.pos[3])
    part.Anchored = true
    part.Color = g.sand and SAND_COLOR or GRASS_COLOR
    part.Material = Enum.Material.SmoothPlastic
    part.CustomPhysicalProperties = terrainPhysics
    part:SetAttribute("RenderRole", "Ground")
    part:SetAttribute("Surface", g.sand and "Sand" or "Grass")
    part.Parent = Workspace
end

-- Remove ground parts from earlier layouts that aren't in the current groundParts list.
local currentGroundNames = {}
for _, g in ipairs(groundParts) do
    currentGroundNames[g.name] = true
end
for _, legacyName in ipairs({ "Ground", "GroundNE", "GroundNW", "GroundSW", "GroundSE", "GroundE" }) do
    if not currentGroundNames[legacyName] then
        local stale = findWorkspaceChild(legacyName)
        if stale then
            stale:Destroy()
        end
    end
end

