-- On the block grid (ADR-005): heights are whole blocks and every face lies on a cell boundary (an odd multiple of
-- 1.25), so blocks set against a mesa sit flush and its top is a block layer. An odd number of cells across puts the
-- centre on a cell centre (a multiple of 2.5), an even number on a boundary.
local mesas, perFeature = {}, {}
for _, r in ipairs(ISLAND.rock) do
    local h = r[5] * BLOCK_SIZE
    perFeature[r[6]] = (perFeature[r[6]] or 0) + 1
    table.insert(mesas, { name = r[6] .. "_" .. perFeature[r[6]], size = {r[3], h, r[4]}, pos = {r[1], h / 2, r[2]},
        feature = r[6] })
end

for _, m in ipairs(mesas) do
    local mesa = findWorkspaceChild(m.name) or Instance.new("Part")
    mesa.Name = m.name
    mesa.Size = Vector3.new(m.size[1], m.size[2], m.size[3])
    mesa.Position = Vector3.new(m.pos[1], m.pos[2], m.pos[3])
    mesa.Anchored = true
    mesa.Color = ROCK_TERRAIN_COLOR
    mesa.CustomPhysicalProperties = terrainPhysics
    mesa:SetAttribute("RenderRole", "Mesa")
    mesa:SetAttribute("Surface", "Rock")
    mesa:SetAttribute("Feature", m.feature) -- the mind sees the Peak, not its hundreds of terraces
    mesa.Parent = Workspace
end

-- Trees (Godling): two groves and a few loners on open ground. Each collides as its trunk only; the renderer
-- draws art/build_props.py's tree, fitted to the part's height. Trunks are one block thick on the grid and 20 tall,
-- so a tree clearly holds the two 7.5 logs it is felled into; about 10 apart, the wide crowns read as separate trees.
local TREE_SIZE = {2.5, 20, 2.5}
local PALM_Y = 10 - SAND_DROP -- palms stand on the sand, a hand lower than the grass
local trees = {}
for n, p in ipairs(ISLAND.trees) do -- a jungle inland, east of the camp
    table.insert(trees, { name = "Tree_" .. n, pos = {p[1], 10, p[2]} })
end
-- Coconut palms, on the beach, inland and on the islet; felled, they give logs like any tree. A palm leans along its
-- part's +X; the generator gives each a quarter-turn yaw (on the beach, out to sea) that keeps the trunk on the grid.
for n, p in ipairs(ISLAND.palms) do -- palms everywhere, as on the Cast Away island; on the sand a hand lower
    table.insert(trees, { name = "Palm_" .. n, pos = {p[1], p[4] and PALM_Y or 10, p[2]}, palm = true, yaw = p[3] })
end
for _, t in ipairs(trees) do
    t.size = TREE_SIZE
    t.model = t.palm and "asset://palm.glb" or "asset://tree.glb"
end

for _, t in ipairs(trees) do
    local tree = findWorkspaceChild(t.name) or Instance.new("Part")
    tree.Name = t.name
    tree.Size = Vector3.new(t.size[1], t.size[2], t.size[3])
    tree.CFrame = CFrame.new(Vector3.new(t.pos[1], t.pos[2], t.pos[3])) * CFrame.fromOrientation(0, math.rad(t.yaw or 0), 0)
    tree.Anchored = true
    tree.Color = Color3.fromRGB(120, 80, 50)
    tree.CustomPhysicalProperties = terrainPhysics
    tree:SetAttribute("RenderRole", "Tree")
    tree:SetAttribute("ModelUrl", t.model)
    tree.Parent = Workspace
    t.part = tree -- felling turns it into a stump and regrowing restores it from this definition
end

