for i = 0, 11 do
    baseBlockPile[i + 1] = { color = "Slate", pos = Vector3.new(ISLAND.pile[1] + (i % 4) * BLOCK_SIZE, BLOCK_SIZE / 2,
        ISLAND.pile[2] + math.floor(i / 4) * BLOCK_SIZE) }
end

for index, blockDef in ipairs(baseBlockPile) do
    createBlock("Block_" .. index, blockDef.pos, blockDef.color)
end
impactBlockCounter = #baseBlockPile

local rock = createRock("Rock_1", ROCK_SPAWN_POSITION, ROCK_SIZE)

if ENABLE_LARGE_RING then
    createRing("Ring_1", Vector3.new(40, 0.28 - SAND_DROP, -42), "Yellow", { 0, 32, 0 }, Vector3.new(3.6, 0.56, 3.6))
