Players.PlayerAdded:Connect(function(player)
    setupPlayer(player, true)
end)
Players.PlayerRemoving:Connect(cleanupPlayer)

for _, player in ipairs(Players:GetPlayers()) do
    setupPlayer(player, false)
end

print("=== Mesa World ===")
